import { Component, ViewChild, ElementRef } from '@angular/core';
import { FormBuilder, FormGroup, Validators } from '@angular/forms';
import { Camera } from '@ionic-native/camera';
import { IonicPage, NavController, ViewController, Platform } from 'ionic-angular';
import { Geolocation } from '@ionic-native/geolocation';
import { GoogleMaps } from '../../providers/google-maps/google-maps';
import { Connectivity } from '../../providers/connectivity/connectivity';

@IonicPage()
@Component({
  selector: 'page-segnalazioni',
  templateUrl: 'segnalazioni.html'
})
export class SegnalazioniPage {
  @ViewChild('fileInput') fileInput;

  @ViewChild('map') mapElement: ElementRef;
  @ViewChild('pleaseConnect') pleaseConnect: ElementRef;

  isReadyToSave: boolean;

  item: any;

  isOnline: boolean

  form: FormGroup;

  constructor(
    public navCtrl: NavController, 
    public viewCtrl: ViewController, 
    formBuilder: FormBuilder, 
    public camera: Camera,
    public geolocation: Geolocation,
    public maps: GoogleMaps, 
    public connectivityService: Connectivity,
    public platform: Platform
    ) {
    this.form = formBuilder.group({
      profilePic: [''],
      name: ['', Validators.required],
      about: ['']
    });
    this.isOnline = navigator.onLine;
    // Watch the form for changes, and
    this.form.valueChanges.subscribe((v) => {
      this.isReadyToSave = this.isOnline&&this.form.valid;
    });
  }

  ionViewDidLoad() {
    // let locationOptions = {timeout: 10000, enableHighAccuracy: true};
    // this.geolocation.getCurrentPosition(locationOptions).then((position) => {
 
    //   // let latLng = new google.maps.LatLng(position.coords.latitude, position.coords.longitude);
 
    //   // let mapOptions = {
    //   //   center: latLng,
    //   //   zoom: 15,
    //   //   mapTypeId: google.maps.MapTypeId.ROADMAP
    //   // }
 
    //   // this.map = new google.maps.Map(this.mapElement.nativeElement, mapOptions);
    //   console.log("localizzato",position.coords.latitude, position.coords.longitude)
 
    // }, (err) => {
    //   console.log("errore nella localizzazione")
    //   console.log(err);
    // });
    let mapLoaded = this.maps.init(this.mapElement.nativeElement, this.pleaseConnect.nativeElement).then(() => {

     // this.autocompleteService = new google.maps.places.AutocompleteService();
      //this.placesService = new google.maps.places.PlacesService(this.maps.map);
      //this.searchDisabled = false;
      
      }); 
    this.addConnectivityListeners();

  }

  addConnectivityListeners(): void {

    this.connectivityService.watchOnline().subscribe(() => {
console.log("online")
      this.isOnline=true;
      this.isReadyToSave = this.form.valid;
    });

    this.connectivityService.watchOffline().subscribe(() => {
console.log("offline")
      this.isOnline=false;
      this.isReadyToSave = false;
    });

  }

  getPicture() {
    if (Camera['installed']()) {
      this.camera.getPicture({
        destinationType: this.camera.DestinationType.DATA_URL,
        targetWidth: 96,
        targetHeight: 96
      }).then((data) => {
        this.form.patchValue({ 'profilePic': 'data:image/jpg;base64,' + data });
      }, (err) => {
        alert('Unable to take photo');
      })
    } else {
      this.fileInput.nativeElement.click();
    }
  }

  processWebImage(event) {
    let reader = new FileReader();
    reader.onload = (readerEvent) => {

      let imageData = (readerEvent.target as any).result;
      this.form.patchValue({ 'profilePic': imageData });
    };

    reader.readAsDataURL(event.target.files[0]);
  }

  getProfileImageStyle() {
    return 'url(' + this.form.controls['profilePic'].value + ')'
  }

  /**
   * The user cancelled, so we dismiss without sending data back.
   */
  cancel() {
    this.viewCtrl.dismiss();
  }

  /**
   * The user is done and wants to create the item, so return it
   * back to the presenter.
   */
  done() {
    if (!this.form.valid) { return; }
    this.viewCtrl.dismiss(this.form.value);
  }
}



